-- cert-fornecedores-categorias.sql — Certificação › Fornecedores: categorias (abas do CL 07) com os seus itens (05/11/2026).
-- Pedido do Guilherme: "faça igual a planilha, tem abas em baixo e cada fornecedor tem seus itens… se criarmos
-- por categoria, tipo as abas, vc já vincula os itens pedidos de cada aba à categoria, e depois quando eu for
-- add um novo fornecedor vinculo ele à categoria" e "sou obrigado a fazer essa avaliação anualmente e quando
-- renova o contrato, então já deixe padronizado isso para todos".
--  · cfo_categorias: uma linha por aba do CL 07, com os itens pedidos (cl07_itens) e, quando houver, as
--    perguntas da avaliação por entrega do FORM 023 (f23_itens). Editável no app (Cadastros).
--  · PCMSO, PGR e trabalho infantil entram em todas as categorias pelo app (não ficam na tabela).
--  · cfo_fornecedores.cl07_lista guarda a lista de itens usada no CL 07 preenchido: mudar um item da
--    categoria vale a partir do próximo CL 07 (anual ou na renovação do contrato).
-- Pode rodar de novo. Migração "cert_fornecedores_categorias".

create table if not exists public.cfo_categorias (
  id text primary key,
  nome text not null,
  ordem int not null default 100,
  forn text not null default 'Fornecedor',     -- como chamar o fornecedor (Viveiro, Empresa…)
  lote boolean not null default false,          -- FORM 023 pede nº do lote
  nf boolean not null default false,            -- FORM 023 pede nota fiscal
  rot_nf text,
  cl07_itens jsonb not null default '[]'::jsonb,   -- [[chave, texto, conforme_quando_NAO?], …]
  f23_itens jsonb not null default '[]'::jsonb,    -- [[chave, pergunta], …] — vazio = só o CL 07
  ativo boolean not null default true,
  criado_em timestamptz not null default now(),
  atualizado_em timestamptz not null default now(),
  atualizado_por text
);
drop trigger if exists cfo_cat_carimbo on public.cfo_categorias;
create trigger cfo_cat_carimbo before update on public.cfo_categorias for each row execute function public.marcar_atualizacao();
alter table public.cfo_categorias enable row level security;
revoke all on public.cfo_categorias from anon;
grant select, insert, update, delete on public.cfo_categorias to authenticated;
drop policy if exists cfoc_leem on public.cfo_categorias;
drop policy if exists cfoc_inserem on public.cfo_categorias;
drop policy if exists cfoc_alteram on public.cfo_categorias;
create policy cfoc_leem on public.cfo_categorias for select to authenticated using (public.app_pode('cert'));
create policy cfoc_inserem on public.cfo_categorias for insert to authenticated with check (public.app_pode('cert'));
create policy cfoc_alteram on public.cfo_categorias for update to authenticated using (public.app_pode('cert')) with check (public.app_pode('cert'));
-- categoria usada não se apaga: desativa (ativo = false)

