-- A categoria agora vem da tabela (dá para criar novas no app).
alter table public.cfo_fornecedores drop constraint if exists cfo_fornecedores_categoria_check;
alter table public.cfo_fornecedores drop constraint if exists cfo_fornecedores_categoria_fk;
alter table public.cfo_fornecedores add constraint cfo_fornecedores_categoria_fk foreign key (categoria) references public.cfo_categorias(id) on update cascade;
alter table public.cfo_avaliacoes drop constraint if exists cfo_avaliacoes_categoria_check;

-- Lista de itens usada no CL 07 já preenchido (mudança na categoria vale no próximo).
alter table public.cfo_fornecedores add column if not exists cl07_lista jsonb;
